<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Certificación {{ $certificacion->folio }}</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font-family:Georgia,serif;color:#172536;margin:0;padding:35px;background:#f4f6f8}.sheet{max-width:850px;min-height:520px;margin:auto;padding:55px;border:8px double #991b32;background:white;text-align:center}.seal{font-size:13px;line-height:1.6}.sheet h1{margin:50px 0 25px;font-size:29px;color:#991b32}.body{font-size:19px;line-height:1.8}.folio{margin:28px;font-size:16px;font-weight:bold}.sign{display:flex;justify-content:space-around;margin-top:80px}.actions{text-align:center;margin:20px}.actions button{padding:10px 18px}@media print{body{padding:0;background:white}.sheet{min-height:unset;box-shadow:none}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Imprimir certificación</button></div><main class="sheet"><header class="seal"><strong>UNIVERSIDAD DE EL SALVADOR</strong><br>FACULTAD MULTIDISCIPLINARIA ORIENTAL<br>UNIDAD DE PROYECCIÓN SOCIAL</header><h1>Certificación de horas sociales</h1><p class="body">La Unidad de Proyección Social hace constar que<br><strong>{{ $certificacion->estudiante?->nombre_completo }}</strong><br>con carnet <strong>{{ $certificacion->estudiante?->due }}</strong>, participó en el proyecto<br><strong>{{ $certificacion->proyecto?->titulo }}</strong><br>del área de {{ $certificacion->proyecto?->areaConocimiento?->nombre ?? 'proyección social' }}.</p><p class="folio">Folio: {{ $certificacion->folio }} · Emitida el {{ $certificacion->fecha_emision?->format('d/m/Y') }}</p><div class="sign"><div>____________________________<br>Jefatura UPS</div><div>____________________________<br>Estudiante</div></div></main></body></html>
